import { YieldPrediction, OptimizationResult, RiskAssessment, BenchmarkResult, ClusterInfo, FieldYieldHistory } from 'shared';

const DISCLAIMER =
  'This explanation is generated by the AI layer. ' +
  'All numeric values are computed by deterministic ML models trained on historical data — ' +
  'not estimated or invented by AI.';

const CROP_BASELINES: Record<string, number> = {
  almond: 4100,
  tomato: 84000,
  'processing tomatoes': 84000,
  pistachio: 2950,
  grape: 14000,
  alfalfa: 18000,
};

function hashCode(s: string): number {
  let h = 0;
  for (let i = 0; i < s.length; i++) {
    h = (Math.imul(31, h) + s.charCodeAt(i)) >>> 0;
  }
  return h;
}

export function computeMockYield(fieldId: string, cropName: string): YieldPrediction {
  const normCrop = cropName.toLowerCase().replace(/s$/, ''); // trim trailing 's' e.g. almonds -> almond
  const baseline = CROP_BASELINES[normCrop] ?? CROP_BASELINES[cropName.toLowerCase()] ?? 4100;
  const predicted = Math.round(baseline * (0.92 + (hashCode(fieldId) % 100) / 500));
  const interval = Math.round(predicted * 0.12);
  const water = 0.38;
  const nutrient = 0.29;

  return {
    field_id: fieldId,
    crop_name: cropName,
    crop_year: 2026,
    predicted_yield_kg_ha: predicted,
    yield_lower_kg_ha: predicted - interval,
    yield_upper_kg_ha: predicted + interval,
    baseline_yield_kg_ha: baseline,
    confidence: 'high',
    factor_water: water,
    factor_nutrient: nutrient,
    factor_heat: 0.15,
    factor_uv: 0.08,
    factor_seed: 0.06,
    factor_planting: 0.04,
    limiting_factors: ['water', 'nutrient'],
    explanation:
      `The model predicts ${predicted.toLocaleString()} kg/ha for ${cropName} — ` +
      `${((predicted - baseline) / baseline * 100).toFixed(1)}% ` +
      `${predicted >= baseline ? 'above' : 'below'} the ${baseline.toLocaleString()} kg/ha historical baseline. ` +
      `Water accounts for ${Math.round(water * 100)}% and nutrients ${Math.round(nutrient * 100)}% of sensitivity. ` +
      `Confidence is high based on available historical records.`,
    disclaimer: DISCLAIMER,
  };
}

export function computeMockOptimize(
  fieldId: string,
  irrigationIn?: number,
  nitrogenLbAc?: number
): OptimizationResult {
  const hash = hashCode(fieldId);
  const currentIrrigation = irrigationIn ?? (38 + (hash % 10));
  const currentNitrogen = nitrogenLbAc ?? (160 + (hash % 40));

  const recIrrigation = currentIrrigation + 4.5;
  const recNitrogen = currentNitrogen + 30.0;

  const baselineYield = 4120 + (hash % 300);
  const expectedYield = Math.round(baselineYield * 1.063);
  const expectedYieldGainPct = 6.3;

  return {
    field_id: fieldId,
    crop_year: 2026,
    current_irrigation_in: currentIrrigation,
    rec_irrigation_in: recIrrigation,
    irrigation_delta_in: 4.5,
    current_nitrogen_lb_ac: currentNitrogen,
    rec_nitrogen_lb_ac: recNitrogen,
    nitrogen_delta_lb_ac: 30.0,
    expected_yield_kg_ha: expectedYield,
    expected_yield_gain_pct: expectedYieldGainPct,
    baseline_yield_kg_ha: baselineYield,
    confidence: 'medium',
    explanation:
      `The optimizer recommends to increase irrigation by 4.5 in and apply 30 lb/ac more nitrogen. ` +
      `This is projected to improve yield by 6.3% (confidence: medium). ` +
      `Recommendations are derived from partial-dependence analysis over the trained yield model.`,
    disclaimer: DISCLAIMER,
  };
}

