export function computeMockBenchmark(fieldId: string): BenchmarkResult {
  const hash = hashCode(fieldId);
  const pct = 55 + (hash % 30);
  const clusterLabel = hash % 6;
  const clusterNames = [
    'High-input intensive',
    'Mixed cohort 1',
    'Low-input conservative',
    'Irrigation-intensive',
    'Nutrient-intensive',
    'Mixed cohort 5',
  ];
  const clusterName = clusterNames[clusterLabel] || 'Mixed cohort 1';

  return {
    field_id: fieldId,
    crop_year: 2026,
    cluster_label: clusterLabel,
    cluster_name: clusterName,
    yield_kg_ha: 4380 + (hash % 200),
    percentile_rank: pct,
    cohort_size: 47 + (hash % 10),
    explanation:
      `This field ranks at the ${pct}th percentile within its peer group: ` +
      `"${clusterName}" (${47 + (hash % 10)} comparable fields). ` +
      `Percentile ranking is based on k-means cohort assignment using agronomic input features.`,
    disclaimer: DISCLAIMER,
  };
}

