export function computeMockFieldHistory(fieldId: string, cropName: string): FieldYieldHistory {
  const hash = hashCode(fieldId);
  const normCrop = cropName.toLowerCase().replace(/s$/, '');
  const baseline = CROP_BASELINES[normCrop] ?? CROP_BASELINES[cropName.toLowerCase()] ?? 4100;

  const history = [2022, 2023, 2024, 2025].map((year) => {
    const variance = 0.85 + ((hash + year) % 100) / 333; // ~0.85 to 1.15
    const yieldAmount = Math.round(baseline * variance);
    const irrigation = parseFloat((35 + ((hash + year) % 15) + (year % 3)).toFixed(1));
    const nitrogen = 140 + ((hash + year) % 60) + (year % 10);

    return {
      crop_year: year,
      yield_kg_ha: yieldAmount,
      irrigation_in: irrigation,
      nitrogen_applied_lb_ac: nitrogen,
    };
  });

  return {
    field_id: fieldId,
    crop_name: cropName,
    history,
  };
}
